#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 305, M = 128;

int n, k, m, a[N], c[N], len[N], w[N], L[N], R[N], f[N][N][M], g[N][N][M], sum;
bool vis[N];

void init() {}

void solve()
{
	cin >> n >> k;
	for (int i = 1; i <= n; ++i)
		cin >> a[i];
	for (int i = 1, x; i <= k; ++i)
	{
		cin >> x;
		vis[x] = 1;
	}
	vis[0] = vis[n + 1] = 1;
	a[0] = a[n + 1] = 1e9;
	k = 0;
	for (int i = 1, lst = 0; i <= n; ++i)
	{
		if (vis[i])
		{
			if (vis[i - 1])
			{
				sum += max(a[i], a[i - 1]);
				continue;
			}
			len[++k] = i - lst - 1;
			L[k] = min(a[i], a[lst]), R[k] = min(a[i], a[lst]);
		}
		else
		{
			c[++m] = a[i];
			sum += a[i];
		}
	}
	sort(c + 1, c + m + 1);
	for (int s = 0; s < 1 << k; ++s)
	{
		for (int i = 1; i <= k; ++i)
		{
			if ((s >> (i - 1)) & 1)
				w[s] += len[i];
		}
	}
	for (int d = 1; d <= n; ++d)
	{
		for (int l = 1, r = d; r <= n; ++l, ++r)
		{
			for (int s = 0, x; s < 1 << k; ++s)
			{
				f[l][r][s] = 1e9;
				if (!s)
					continue;
				if (w[s] > r - l + 1)
				{
					g[l][r][s] = 1e9;
					continue;
				}
				if (d == 1)
				{
					x = __lg(s & -s) + 1;
					g[l][r][s] = f[l][r][s] = L[x] + max(c[r], R[x]) - min(c[r], R[x]);
				}
				for (int i = 1; i <= k; ++i)
				{
					if (!((s >> (i - 1)) & 1) || len[i] < 2)
						continue;
					f[l][r][s] = min(f[l][r][s], g[l + 1][r - 1][s ^ (1 << (i - 1))] + L[i] + max(c[r], R[i]) - min(c[l], L[i]));
				}
				g[l][r][s] = min({f[l][r][s], g[l + 1][r][s], g[l][r - 1][s]});
				for (int t = s; t; t = (t - 1) & s)
					g[l][r][s] = g[l][l + w[t] - 1][t] + g[l + w[t]][r][s ^ t];
			}
		}
	}
	cout << g[1][m][(1 << k) - 1] + sum << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

